  <header className="mb-10"><p className="text-sm font-bold uppercase tracking-widest text-blue-700">Biblioteca de ejercicios · Nivel A1</p><h1 className="mt-3 text-4xl font-black leading-tight tracking-tight text-slate-950 sm:text-5xl">Ejercicios de inglés A1 – Unidad {u.n}: {u.title}</h1><p className="mt-5 text-lg leading-8 text-slate-600">{u.description}</p></header>
